shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ece6d9;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c0af;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.14);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --crimson: #8f2424;
    --font-serif-en: 'Playfair Display', Georgia, serif;
    --font-body-en: 'Lora', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  .wsj-shadow-body {
    background-color: var(--paper);
    color: var(--body);
    font-family: var(--font-body-en), var(--font-serif-cn);
    line-height: 1.75;
    overflow-x: hidden;
  }

  /* Language Switching Protocol */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  :host([lang="zh-CN"]) .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    line-height: 1.88;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-body-en);
    line-height: 1.72;
  }

  /* Highlighting */
  mark.ed-hl {
    background: linear-gradient(120deg, rgba(184, 93, 25, 0.18) 0%, rgba(184, 93, 25, 0.26) 100%);
    color: var(--ink);
    padding: 0.08em 0.28em;
    border-bottom: 1.5px solid var(--accent);
    border-radius: 2px;
    font-weight: 600;
  }

  /* Top Masthead */
  .wsj-masthead {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(250, 248, 244, 0.96);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--ink);
    box-shadow: 0 1px 0 var(--line);
  }

  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    padding: 0.65rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-cluster {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    flex-wrap: wrap;
  }

  .wsj-wordmark {
    font-family: var(--font-serif-en);
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.08em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .section-pill {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 0.18rem 0.55rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    color: var(--muted);
  }

  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--ink);
    background: var(--paper-card);
    border-radius: 2px;
    overflow: hidden;
  }

  .lang-btn {
    appearance: none;
    border: none;
    background: transparent;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.35rem 0.75rem;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.18s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Main Container */
  .page-shell {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 5rem;
  }

  /* Hero Header */
  .article-hero {
    border-bottom: 3px double var(--ink);
    padding-bottom: 2.2rem;
    margin-bottom: 2.5rem;
  }

  .kicker-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 1rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--line);
  }

  .kicker-tag {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: var(--accent);
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
  }

  .kicker-tag::before {
    content: "";
    display: inline-block;
    width: 8px;
    height: 8px;
    background: var(--accent);
  }

  .folio-meta {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
    letter-spacing: 0.05em;
  }

  .hero-title {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-weight: 800;
    font-size: clamp(2.1rem, 4.3vw, 3.45rem);
    line-height: 1.16;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 1.25rem;
    max-width: 960px;
  }

  :host([lang="zh-CN"]) .hero-title {
    font-family: var(--font-serif-cn);
    line-height: 1.26;
    letter-spacing: 0.01em;
  }

  .hero-summary-strip {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 1.5rem;
    align-items: end;
    padding-top: 1rem;
    border-top: 1px solid var(--line);
  }

  .byline-block {
    font-family: var(--font-sans);
    font-size: 0.85rem;
    color: var(--muted);
  }

  .byline-authors {
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-right: 0.75rem;
  }

  .byline-date {
    font-family: var(--font-mono);
    font-size: 0.78rem;
  }

  .statute-badge {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    background: var(--navy-bg);
    color: #f3efe6;
    padding: 0.45rem 0.85rem;
    border-left: 3px solid var(--accent);
    letter-spacing: 0.04em;
  }

  /* Editorial Grid Architecture */
  .editorial-grid {
    display: grid;
    grid-template-columns: minmax(0, 7fr) minmax(280px, 4.5fr);
    gap: 3rem;
    align-items: start;
  }

  .narrative-col {
    min-width: 0;
  }

  .dossier-rail {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
    position: sticky;
    top: 4.5rem;
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.45rem;
  }

  .prose-lead {
    font-size: 1.26rem;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.65rem;
    line-height: 1.68;
  }

  :host([lang="zh-CN"]) .prose-lead {
    line-height: 1.82;
  }

  /* Section Dividers inside Narrative */
  .section-marker {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin: 2.2rem 0 1.25rem;
    padding-top: 0.5rem;
  }

  .section-marker-num {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--paper);
    background: var(--ink);
    padding: 0.15rem 0.45rem;
    letter-spacing: 0.06em;
  }

  .section-marker-title {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--ink);
  }

  .section-marker-line {
    flex: 1;
    height: 1px;
    background: var(--line-strong);
  }

  /* Forensic Statement Callout for p5 & p6 & p7 */
  .legal-dossier-box {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.5rem 1.6rem;
    margin: 1.85rem 0;
  }

  .dossier-box-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid var(--line-strong);
    padding-bottom: 0.65rem;
    margin-bottom: 1.1rem;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }

  .dossier-charge-quote {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.28rem;
    font-weight: 700;
    color: var(--crimson);
    margin-bottom: 1rem;
    padding-bottom: 0.85rem;
    border-bottom: 1px dashed var(--line-strong);
  }

  .no-comment-pill {
    font-family: var(--font-mono);
    font-size: 0.88rem;
    color: var(--muted);
    background: var(--paper);
    border-left: 3px solid var(--muted);
    padding: 0.55rem 0.9rem;
    margin-top: 0.75rem;
    margin-bottom: 0;
  }

  /* Press Freedom Verdict Block for p10 */
  .constitutional-warning {
    background: var(--navy-bg);
    color: #f7f4ed;
    padding: 1.75rem 1.85rem;
    margin: 2rem 0 1.6rem;
    border-left: 4px solid var(--accent);
    position: relative;
  }

  .warning-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #e69d63;
    margin-bottom: 0.75rem;
    display: block;
  }

  .constitutional-warning .prose-p {
    color: #f7f4ed;
    font-size: 1.14rem;
    margin-bottom: 0;
    line-height: 1.75;
  }

  .constitutional-warning mark.ed-hl {
    background: rgba(230, 157, 99, 0.25);
    color: #fff;
    border-bottom-color: #e69d63;
  }

  /* Corporate Disclosure Footer Note (p11) */
  .disclosure-footnote {
    margin-top: 2.2rem;
    padding-top: 1rem;
    border-top: 1px solid var(--line-strong);
    font-family: var(--font-sans);
    font-size: 0.88rem;
    color: var(--muted);
    font-style: italic;
  }

  /* Right Rail Cards */
  .rail-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem;
  }

  .rail-card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 2px solid var(--ink);
    padding-bottom: 0.55rem;
    margin-bottom: 1rem;
  }

  .rail-card-title {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--ink);
  }

  .rail-card-code {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--accent);
    font-weight: 600;
  }

  .rail-svg-wrap {
    width: 100%;
    overflow: hidden;
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 0.5rem;
  }

  .rail-caption {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    color: var(--muted);
    margin-top: 0.75rem;
    line-height: 1.5;
  }

  /* Derived Pull Quote in Rail */
  .pull-quote {
    background: var(--paper);
    border: 1px solid var(--line-strong);
    border-left: 4px solid var(--ink);
    padding: 1.25rem 1.35rem;
  }

  .pull-quote .quote-text {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.02rem;
    font-weight: 600;
    color: var(--ink);
    margin-bottom: 0.65rem;
    line-height: 1.55;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.73rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Escalation Matrix Bottom Section */
  .escalation-ledger {
    margin-top: 3.5rem;
    padding-top: 2rem;
    border-top: 2px solid var(--ink);
  }

  .ledger-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.5rem;
  }

  .ledger-title {
    font-family: var(--font-serif-en), var(--font-serif-cn);
    font-size: 1.45rem;
    font-weight: 700;
    color: var(--ink);
  }

  .ledger-sub {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }

  .ledger-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.25rem;
  }

  .ledger-step {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.15rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .ledger-step.active-probe {
    border-top-color: var(--accent);
    background: #f6efe4;
  }

  .step-date {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 0.45rem;
  }

  .step-head {
    font-family: var(--font-sans);
    font-size: 0.95rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.5rem;
  }

  .step-desc {
    font-size: 0.84rem;
    color: var(--body);
    line-height: 1.55;
    margin-bottom: 0.85rem;
  }

  .step-target {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--muted);
    border-top: 1px solid var(--line);
    padding-top: 0.45rem;
  }

  /* Responsive Breakpoints */
  @media (max-width: 960px) {
    .editorial-grid {
      grid-template-columns: 1fr;
      gap: 2.25rem;
    }
    .dossier-rail {
      position: static;
    }
    .ledger-grid {
      grid-template-columns: repeat(2, 1fr);
    }
    .hero-summary-strip {
      grid-template-columns: 1fr;
      gap: 0.85rem;
    }
  }

  @media (max-width: 600px) {
    .page-shell {
      padding: 1.5rem 1rem 3.5rem;
    }
    .masthead-inner {
      padding: 0.55rem 1rem;
    }
    .ledger-grid {
      grid-template-columns: 1fr;
    }
    .hero-title {
      font-size: 1.85rem;
    }
    .prose-lead {
      font-size: 1.12rem;
    }
    .prose-p {
      font-size: 1.04rem;
    }
  }
